svg.script:
(function() {
  var currentAngle = 50;

  // Origin point: Fúrcula Vaginal
  var ox = 290;
  var oy = 338;
  var vectorLen = 160;

  function setAngle(angle) {
    currentAngle = angle;

    // Update active button state
    var btns = [0, 50, 75];
    btns.forEach(function(a) {
      var btn = document.getElementById('a12p19h-btn-' + a);
      if (btn) {
        if (a === angle) {
          btn.classList.add('a12p19h-active');
        } else {
          btn.classList.remove('a12p19h-active');
        }
      }
    });

    // Calculate dynamic incision line end point
    var rad = angle * Math.PI / 180;
    var dx = - Math.sin(rad) * vectorLen;
    var dy = Math.cos(rad) * vectorLen;

    var ex = ox + dx;
    var ey = oy + dy;

    // Update line element
    var lineEl = document.getElementById('a12p19h-inc-line-el');
    if (lineEl) {
      lineEl.setAttribute('x2', ex);
      lineEl.setAttribute('y2', ey);
    }

    // Update cut node marker along vector
    var nodeRatio = 0.45;
    var nx = ox + dx * nodeRatio;
    var ny = oy + dy * nodeRatio;

    var cutNode = document.getElementById('a12p19h-inc-cut-node');
    var cross1 = document.getElementById('a12p19h-cut-cross1');
    var cross2 = document.getElementById('a12p19h-cut-cross2');

    if (cutNode) {
      cutNode.setAttribute('cx', nx);
      cutNode.setAttribute('cy', ny);
    }
    if (cross1) {
      cross1.setAttribute('x1', nx - 6); cross1.setAttribute('y1', ny - 6);
      cross1.setAttribute('x2', nx + 6); cross1.setAttribute('y2', ny + 6);
    }
    if (cross2) {
      cross2.setAttribute('x1', nx - 6); cross2.setAttribute('y1', ny + 6);
      cross2.setAttribute('x2', nx + 6); cross2.setAttribute('y2', ny - 6);
    }

    // Update muscle statuses based on angle
    var cardBe = document.getElementById('a12p19h-card-be');
    var cardTs = document.getElementById('a12p19h-card-ts');
    var cardEa = document.getElementById('a12p19h-card-ea');
    var cardIc = document.getElementById('a12p19h-card-ic');

    var bgBe = document.getElementById('a12p19h-badge-bg-be');
    var txtBe = document.getElementById('a12p19h-badge-txt-be');
    var stBe = document.getElementById('a12p19h-status-be');

    var bgTs = document.getElementById('a12p19h-badge-bg-ts');
    var txtTs = document.getElementById('a12p19h-badge-txt-ts');
    var stTs = document.getElementById('a12p19h-status-ts');

    var bgEa = document.getElementById('a12p19h-badge-bg-ea');
    var txtEa = document.getElementById('a12p19h-badge-txt-ea');
    var stEa = document.getElementById('a12p19h-status-ea');

    var bgIc = document.getElementById('a12p19h-badge-bg-ic');
    var txtIc = document.getElementById('a12p19h-badge-txt-ic');
    var stIc = document.getElementById('a12p19h-status-ic');

    var pathBe = document.getElementById('a12p19h-path-be-r');
    var pathTs = document.getElementById('a12p19h-path-ts-r');
    var pathEa = document.getElementById('a12p19h-path-ea-outer');
    var pathIc = document.getElementById('a12p19h-path-ic-r');

    if (angle === 0) {
      // MEDIAN EPISIOTOMY (0°)
      if (cardBe) cardBe.className.baseVal = 'a12p19h-card a12p19h-cut';
      if (bgBe) bgBe.setAttribute('fill', 'var(--a12p19h-accent-red, #ff4757)');
      if (txtBe) txtBe.textContent = 'SECCIONADO';
      if (stBe) stBe.textContent = 'Cruzado medialmente na fúrcula.';

      if (cardTs) cardTs.className.baseVal = 'a12p19h-card a12p19h-spared';
      if (bgTs) bgTs.setAttribute('fill', 'var(--a12p19h-accent-green, #2ecc71)');
      if (txtTs) txtTs.textContent = 'POUPADO';
      if (stTs) stTs.textContent = 'Vetor de 0° passa paralelo ao músculo.';

      if (cardEa) cardEa.className.baseVal = 'a12p19h-card a12p19h-cut';
      if (bgEa) bgEa.setAttribute('fill', 'var(--a12p19h-accent-red, #ff4757)');
      if (txtEa) txtEa.textContent = 'LACERAÇÃO 3º/4º';
      if (stEa) stEa.textContent = 'ALERTA: Vetor atinge diretamente o esfíncter!';

      if (cardIc) cardIc.className.baseVal = 'a12p19h-card a12p19h-spared';
      if (bgIc) bgIc.setAttribute('fill', 'var(--a12p19h-accent-green, #2ecc71)');
      if (txtIc) txtIc.textContent = 'POUPADO';
      if (stIc) stIc.textContent = 'Preservado lateralmente.';

      // Visual fills on muscles
      if (pathBe) pathBe.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathTs) pathTs.setAttribute('fill', 'url(#a12p19h-spared-muscle-grad)');
      if (pathEa) pathEa.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathIc) pathIc.setAttribute('fill', 'url(#a12p19h-spared-muscle-grad)');

    } else if (angle >= 45 && angle <= 60) {
      // MEDIOLATERAL (45°-60°) - GOLD STANDARD
      if (cardBe) cardBe.className.baseVal = 'a12p19h-card a12p19h-cut';
      if (bgBe) bgBe.setAttribute('fill', 'var(--a12p19h-accent-red, #ff4757)');
      if (txtBe) txtBe.textContent = 'SECCIONADO';
      if (stBe) stBe.textContent = 'Cruzado logo no início da incisão junto à fúrcula.';

      if (cardTs) cardTs.className.baseVal = 'a12p19h-card a12p19h-cut';
      if (bgTs) bgTs.setAttribute('fill', 'var(--a12p19h-accent-red, #ff4757)');
      if (txtTs) txtTs.textContent = 'SECCIONADO';
      if (stTs) stTs.textContent = 'Seccionado no trajeto médio rumo à tuberosidade.';

      if (cardEa) cardEa.className.baseVal = 'a12p19h-card a12p19h-spared';
      if (bgEa) bgEa.setAttribute('fill', 'var(--a12p19h-accent-green, #2ecc71)');
      if (txtEa) txtEa.textContent = 'POUPADO';
      if (stEa) stEa.textContent = 'Protegido na linha média posterior (>15mm de margem).';

      if (cardIc) cardIc.className.baseVal = 'a12p19h-card a12p19h-spared';
      if (bgIc) bgIc.setAttribute('fill', 'var(--a12p19h-accent-green, #2ecc71)');
      if (txtIc) txtIc.textContent = 'POUPADO';
      if (stIc) stIc.textContent = 'Intacto antero-lateralmente junto ao ramo isquiopúbico.';

      // Visual fills on muscles
      if (pathBe) pathBe.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathTs) pathTs.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathEa) pathEa.setAttribute('fill', 'url(#a12p19h-spared-muscle-grad)');
      if (pathIc) pathIc.setAttribute('fill', 'url(#a12p19h-spared-muscle-grad)');

    } else if (angle > 65) {
      // LATERAL INCISION (75°) - EXCESSIVE ANGLE
      if (cardBe) cardBe.className.baseVal = 'a12p19h-card a12p19h-warning';
      if (bgBe) bgBe.setAttribute('fill', 'var(--a12p19h-accent-yellow, #ffa502)');
      if (txtBe) txtBe.textContent = 'PARCIAL';
      if (stBe) stBe.textContent = 'Corte muito lateral desvia do corpo perineal.';

      if (cardTs) cardTs.className.baseVal = 'a12p19h-card a12p19h-cut';
      if (bgTs) bgTs.setAttribute('fill', 'var(--a12p19h-accent-red, #ff4757)');
      if (txtTs) txtTs.textContent = 'SECCIONADO';
      if (stTs) stTs.textContent = 'Seccionado lateralmente.';

      if (cardEa) cardEa.className.baseVal = 'a12p19h-card a12p19h-spared';
      if (bgEa) bgEa.setAttribute('fill', 'var(--a12p19h-accent-green, #2ecc71)');
      if (txtEa) txtEa.textContent = 'POUPADO';
      if (stEa) stEa.textContent = 'Preservado (distância excessiva).';

      if (cardIc) cardIc.className.baseVal = 'a12p19h-card a12p19h-warning';
      if (bgIc) bgIc.setAttribute('fill', 'var(--a12p19h-accent-yellow, #ffa502)');
      if (txtIc) txtIc.textContent = 'RISCO DE LESÃO';
      if (stIc) stIc.textContent = 'ATENÇÃO: Ângulo >70° aproxima do ramo isquiopúbico!';

      // Visual fills on muscles
      if (pathBe) pathBe.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathTs) pathTs.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
      if (pathEa) pathEa.setAttribute('fill', 'url(#a12p19h-spared-muscle-grad)');
      if (pathIc) pathIc.setAttribute('fill', 'url(#a12p19h-cut-muscle-grad)');
    }
  }

  // Attach button click listeners
  var btn0 = document.getElementById('a12p19h-btn-0');
  var btn50 = document.getElementById('a12p19h-btn-50');
  var btn75 = document.getElementById('a12p19h-btn-75');

  if (btn0) btn0.addEventListener('click', function() { setAngle(0); });
  if (btn50) btn50.addEventListener('click', function() { setAngle(50); });
  if (btn75) btn75.addEventListener('click', function() { setAngle(75); });

  // Muscle click listeners to toggle selection/focus
  var muscles = document.querySelectorAll('.a12p19h-muscle');
  for (var i = 0; i < muscles.length; i++) {
    (function(m) {
      m.addEventListener('click', function() {
        var type = m.getAttribute('data-muscle');
        if (type === 'be') setAngle(50);
        else if (type === 'ts') setAngle(50);
        else if (type === 'ea') setAngle(0);
        else if (type === 'ic') setAngle(75);
      });
    })(muscles[i]);
  }

  // Initialize default
  setAngle(50);
})();
